dist=distance_transform_edt(1-target)/SCALE
weights=1+np.minimum(dist/6,3)*2

def tip_path(p):
    u=np.r_[0,np.cumsum(np.linalg.norm(np.diff(p[:,:2],axis=0),axis=1))]
    t=np.linspace(0,u[-1],max(3,int(u[-1]/.8)))
